option.value:
/* ── Base ─────────────────────────────────────────────── */
@import url('https://fonts.googleapis.com/css2?family=Bayon&display=swap');

.landing {
  min-height: 100vh;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: var(--blue);
  position: relative;
  overflow: hidden;
  cursor: none;
}

/* ── Background Text ──────────────────────────────────── */
.landing__bg-text {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  padding-left: 2vw; /* Use vw to scale with screen size */
  z-index: 0;
  pointer-events: none;
  font-family: 'Bayon', sans-serif;
  color: rgba(255, 228, 92, 0.8); /* var(--yellow) is #ffe45c */
  line-height: 0.8; /* Extremely tight line height to stack them closely */
  text-transform: uppercase;
  user-select: none;
  height: 100vh;
  overflow: hidden;
}

.landing__bg-text-line1 {
  /* Fits ~7 characters "YOU ARE" */
  font-size: clamp(8rem, 32vh, 32rem);
  letter-spacing: -0.04em;
  white-space: nowrap;
}

.landing__bg-text-line2 {
  /* Fits ~4 characters "WHAT" - requires largest font size */
  font-size: clamp(12rem, 50vh, 45rem);
  letter-spacing: -0.04em;
  white-space: nowrap;
  /*transform: translateY(-2vh);*/
}

.landing__bg-text-line3 {
  /* Fits ~7 characters "YOU EAT" (plus space) - balances with line 1 */
  font-size: clamp(8rem, 33vh, 32rem);
  letter-spacing: -0.04em;
  white-space: nowrap;
  /*transform: translateY(-4vh);*/
}

/* Mobile: preserve the same vibe but avoid clipping/cutoff */
@media (max-width: 768px) {
  .landing__bg-text {
    padding-left: 0;
    padding-right: 0;
    width: 100%;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
    align-items: flex-start;
    padding-top: 4vh;
    gap: 1.5vw;
    line-height: 1;
  }

  .landing__bg-text-line1,
  .landing__bg-text-line2,
  .landing__bg-text-line3 {
    font-size: clamp(3rem, 12.5vw, 5.5rem);
    letter-spacing: normal;
  }

  .landing__face {
    height: clamp(300px, 75vw, 480px);
    margin-top: 10vh;
  }
}

/* Extra small phones */
@media (max-width: 390px) {
  .landing__bg-text {
    padding-top: 1vh;
    gap: 1vw;
  }

  .landing__bg-text-line1,
  .landing__bg-text-line2,
  .landing__bg-text-line3 {
    font-size: clamp(2.8rem, 9vw, 4.2rem);
  }

  .landing__face {
    height: clamp(260px, 75vw, 380px);
    margin-top: 8vh;
  }
}

/* ── Draggable Icons ──────────────────────────────────── */

.landing__icons-container {
  position: absolute;
  right: 15vw;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 3rem;
  z-index: 10;
  pointer-events: none; /* Let pointer events pass through container */
}

.landing__icon-wrapper {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 1rem;
}

.landing__icon-label {
  font-family: 'Bayon', sans-serif;
  color: var(--text-dark);
  font-size: 1.2rem;
  text-transform: uppercase;
  user-select: none;
  background-color: var(--yellow);
  padding: 0.2rem 0.8rem;
  border-radius: 4px;
}

.landing__icon-img {
  width: 60px;
  height: 60px;
  cursor: grab;
  pointer-events: auto; /* Re-enable pointer events for the icon */
  filter: drop-shadow(0 4px 6px rgba(0,0,0,0.2));
  transition: transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
  touch-action: none; /* Important for pointer events API down/move mapping */
}

.landing__icon-img:active {
  cursor: grabbing;
}

@media (max-width: 768px) {
  .landing__icons-container {
    right: 50%;
    transform: translateX(50%);
    top: auto;
    bottom: 5vh;
    flex-direction: row;
    gap: 2rem;
  }
  .landing__icon-img {
    width: 45px;
    height: 45px;
  }
  .landing__icon-label {
    font-size: 1rem;
  }
}

/* ── Growing circle ───────────────────────────────────── */
.landing__circle {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-color: var(--blue);
  transform: translate(-50%, -50%) scale(0);
  z-index: 1;
  pointer-events: none;
}

.landing--clicked .landing__circle {
  animation: circleExpand 2.4s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes circleExpand {
  from {
    transform: translate(-50%, -50%) scale(0);
    background-color: var(--blue);
  }
  to {
    transform: translate(-50%, -50%) scale(100);
    background-color: var(--blue-dark);
  }
}

/* ── Face wrapper ─────────────────────────────────────── */
.landing__face {
  position: relative;
  z-index: 2;
  height: clamp(350px, 38vw, 700px);
  display: flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 16px 48px rgba(0, 0, 0, 0.18));
  cursor: default;
}

.landing__face-img {
  height: 100%;
  width: auto;
  display: block;
  user-select: none;
  -webkit-user-drag: none;
}

/* ── Mouth click target — 1/4 width, bottom 2/3 of center ─ */
.landing__mouth-target {
  position: absolute;
  width: 25%;
  height: 16.67%;
  top: 45.83%;
  left: 37.5%;
  background: transparent;
  border: none;
  cursor: none;
  padding: 0;
}

/* ── Shrink animation ─────────────────────────────────── */
.landing__face--shrink {
  animation: faceShrink 1.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@keyframes faceShrink {
  0%   { transform: scale(1);    opacity: 1; }
  12%  { transform: scale(1.06); }
  100% { transform: scale(0.7);    opacity: 0.8; }
}

